const body = $input.first().json.body || $input.first().json;
const words = body.words || [];
const raw = body.raw || '';
const lang = body.lang || 'es';
let items = [];

if (words.length > 0) {
  items = words.map(w => {
    if (typeof w === 'string') {
      const idx = w.indexOf(':');
      return idx > -1
        ? { term: w.slice(0, idx).trim(), description: w.slice(idx + 1).trim(), lang }
        : { term: w.trim(), description: '', lang };
    }
    return { term: w.term || w.name || '', description: w.description || '', lang: w.lang || lang };
  });
} else if (raw) {
  items = raw.split('\n')
    .map(l => l.replace(/^[*\-]\s*/, '').trim())
    .filter(Boolean)
    .map(l => {
      const idx = l.indexOf(':');
      return idx > -1
        ? { term: l.slice(0, idx).trim(), description: l.slice(idx + 1).trim(), lang }
        : { term: l.trim(), description: '', lang };
    });
}
return items.filter(i => i.term).map(i => ({ json: i }));

const categories = $input.first().json.category_list?.categories || [];
const cat = categories.find(c => c.slug === 'glosario' || c.name?.toLowerCase() === 'glosario');
if (!cat) throw new Error('Category #glosario not found. Check DISCOURSE_URL or category slug.');
return [{ json: { categoryId: cat.id, categorySlug: cat.slug } }];

const categoryId = $('Extract Category ID').item.json.categoryId;
const discourseUrl = $env.DISCOURSE_URL || 'https://your-discourse-instance.com';
const discourseKey = $env.DISCOURSE_API_KEY;
const discourseUser = $env.DISCOURSE_API_USERNAME || 'system';
const openaiUrl = $env.OPENAI_BASE_URL || 'https://api.openai.com';
const openaiKey = $env.OPENAI_API_KEY;
const openaiModel = $env.OPENAI_MODEL || 'gpt-4o-mini';

const items = $input.all();
const results = [];

function levenshtein(a, b) {
  const m = a.length, n = b.length;
  const d = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) d[i][0] = i;
  for (let j = 0; j <= n; j++) d[0][j] = j;
  for (let i = 1; i <= m; i++)
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + cost);
    }
  return d[m][n];
}

async function searchExisting(term) {
  try {
    const url = discourseUrl + '/search.json?q=' + encodeURIComponent(term) + '%20in%3Atitle%20%23glosario';
    const resp = await fetch(url, { headers: { 'Api-Key': discourseKey, 'Api-Username': discourseUser } });
    if (!resp.ok) return [];
    const data = await resp.json();
    const posts = data.posts || [];
    const topics = data.grouped_search_result?.topics || [];
    return [...posts.map(p => p.topic_title || p.title || ''), ...topics.map(t => t.title || '')].filter(Boolean);
  } catch { return []; }
}

async function generateDescription(term, lang) {
  try {
    const resp = await fetch(openaiUrl + '/chat/completions', {
      method: 'POST',
      headers: { 'Authorization': 'Bearer ' + openaiKey, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: openaiModel,
        messages: [
          { role: 'system', content: 'Write a glossary entry for the given term. Rules: maximum 3 paragraphs. Simple, concise, and precise. Include the key elements a reader expects in a glossary definition. Output only the entry text, no preamble, no title, no formatting markers.' },
          { role: 'user', content: 'Term: ' + term + '\nLanguage: ' + lang }
        ],
        temperature: 0.3,
        max_tokens: 600
      })
    });
    if (!resp.ok) return '';
    const data = await resp.json();
    return data.choices?.[0]?.message?.content || '';
  } catch { return ''; }
}

async function createTopic(term, description, catId) {
  try {
    const resp = await fetch(discourseUrl + '/posts.json', {
      method: 'POST',
      headers: { 'Api-Key': discourseKey, 'Api-Username': discourseUser, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: term,
        raw: '## ' + term + '\n\n' + description + '\n\n---\n*Auto-generated glossary entry*',
        category: catId
      })
    });
    if (!resp.ok) {
      const err = await resp.text();
      return { error: resp.status + ': ' + err };
    }
    const data = await resp.json();
    return { postId: data.id, topicId: data.topic_id };
  } catch (e) { return { error: e.message }; }
}

for (const item of items) {
  const { term, description, lang } = item.json;
  if (!term) continue;

  // 1. Check existence
  const existingTitles = await searchExisting(term);
  const termLower = term.toLowerCase().trim();
  const isDuplicate = existingTitles.some(t => {
    const tLower = t.toLowerCase().trim();
    if (termLower === tLower) return true;
    const maxLen = Math.max(termLower.length, tLower.length);
    if (maxLen === 0) return false;
    return (1 - levenshtein(termLower, tLower) / maxLen) >= 0.85;
  });

  if (isDuplicate) {
    results.push({ json: { term, status: 'skipped', reason: 'duplicate or very similar topic exists' } });
    continue;
  }

  // 2. Generate description if missing
  let desc = description || '';
  if (!desc.trim()) {
    desc = await generateDescription(term, lang);
  }

  if (!desc.trim()) {
    results.push({ json: { term, status: 'error', reason: 'could not generate description' } });
    continue;
  }

  // 3. Create topic
  const createResult = await createTopic(term, desc, categoryId);
  if (createResult.error) {
    results.push({ json: { term, status: 'error', reason: createResult.error } });
  } else {
    results.push({ json: { term, status: 'created', postId: createResult.postId, topicId: createResult.topicId } });
  }
}

return results;
